 "content": "def transform(grid):
    """Fill the hollow interiors of 5-colored open-top frames and project
    each top opening leftward across the row immediately above it in color 2.
    """
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    for comp in components:
        r0 = min(r for r, _ in comp)
        r1 = max(r for r, _ in comp)
        c0 = min(c for _, c in comp)
        c1 = max(c for _, c in comp)
        # Require a rectangular frame with complete vertical sides and bottom,
        # and exactly one gap in its top edge.
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        top_gaps = [c for c in range(c0, c1 + 1) if grid[r0][c] != 5]
        if len(top_gaps) != 1:
            continue
        gap = top_gaps[0]
        if any(grid[r][c0] != 5 or grid[r][c1] != 5 for r in range(r0, r1 + 1)):
            continue
        if any(grid[r1][c] != 5 for c in range(c0, c1 + 1)):
            continue
        if any(grid[r][c] != 0 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)):
            continue
        if r0 > 0:
            for c in range(0, gap + 1):
                out[r0 - 1][c] = 2
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = 2
    return out
